pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2);
        vm.assume(withdrawAmount <= depositAmount);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent);
        uint256 balanceBefore = address(c).balance;
        vm.prank(actor);
        try c.withdraw() {
            uint256 balanceAfter = address(c).balance;
            uint256 remainingBalances = c.balances(actor);
            assertTrue(balanceAfter == remainingBalances);
        } catch {
            assertTrue(false);
        }
    }
}
